------------ lifeCycle ------------

function UIActionPointRankNode:__init()
    self:CleanProperties()
end

function UIActionPointRankNode:__delete()
    self:CleanProperties()
end

function UIActionPointRankNode:Awake()
    SetButtonAction(self.Btn_Detail, Bind(self, self.OnDetailBtnClicked))
    if IsNull(self.LB_PlayerHead.Env) then
        self.LB_PlayerHead:Init()
        self.LB_PlayerHead.Env:SetCallBack(function()
            local playerId = checkNumber(self.data.playerId)
            if playerId > 0 then  -- 机器人不能点
                -- 直接进入个人信息界面2D版
                GameUtils.ShowPlayerInfo(playerId)
            end
        end)
    end
end

function UIActionPointRankNode:Start()
end

function UIActionPointRankNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end
------------ lifeCycle ------------


function UIActionPointRankNode:CleanProperties()
    self.comp = nil
    self.data = nil
end

function UIActionPointRankNode:SetComponent(comp)
    self.comp = comp
end

function UIActionPointRankNode:OnDetailBtnClicked()
    -- print("[大乱斗] 排行榜详情", table.dump(self.data.team, nil, 5))
    GameUtils.ShowCommonTeamsTipsBoard(self.Btn_Detail, self.data.team, nil, nil, self.data.name)
end

function UIActionPointRankNode:Refresh(data)
    if isNull(data) then
        return
    end
    -- print("[大乱斗] cell", table.dump(data, nil, 3))
    self.data = data
    local rank = data.ranking
    local percentageRank = data.percentageRank
    local playerName = data.name
    local avatarId = checkInt(data.avatar)
    local avatarFrameId = checkInt(data.avatarFrame)
    local level = data.level
    local combatValue = data.score
    local isMyself = checkNumber(data.playerId) == checkNumber(GameUtils.GetPlayerId())

    KTool.SetActive(self.RT_MySelf, isMyself)
    if not isNull(rank) and rank > 0 then
        self.Txt_Rank.text = tostring(rank)
        KTool.SetActive(self.Txt_Rank, true)
    else
        KTool.SetActive(self.Txt_Rank, false)
    end

    if not isNull(percentageRank) and percentageRank > 0 then
        self.Txt_RankPercentage.text = tostring(percentageRank) .. "%"
        KTool.SetActive(self.Txt_RankPercentage, true)
    else
        KTool.SetActive(self.Txt_RankPercentage, false)
    end

    self.Txt_CombatValue.text = tostring(combatValue)
    self.Txt_Level.text = string.format("LV.%d", level)
    self.Txt_PlayerName.text = playerName
    self.LB_PlayerHead.Env:FreshAvatarFrame(avatarId, avatarFrameId)

    if not isNull(rank) and rank > 0 then
        self.SImg_Rank1.Status = rank > 4 and 4 or rank
        if not isNull(self.SImg_Rank2) then
            self.SImg_Rank2.Status = rank > 4 and 4 or rank
        end
    else
        self.SImg_Rank1.Status = 4
        if not isNull(self.SImg_Rank2) then
            self.SImg_Rank2.Status = 4
        end
    end

    if not IsNull(self.RT_NoRank) then
        KTool.SetActive(self.RT_NoRank, isNull(rank) or rank == 0)
    end

    KTool.SetActive(self.Btn_Detail, isNotNull(data.team))
end

return UIActionPointRankNode